#include <iostream>
#include <map>
#include <queue>
#include <set>
#include <stack>
#include <string>

int main() {
    std::map<std::string, int> edades;
    edades["ana"] = 30;
    edades["luis"] = 25;
    std::cout << edades.size() << '\n';   // 2

    std::set<int> unicos{3, 1, 3, 2};
    std::cout << unicos.size() << '\n';   // 3
    for (int x : unicos) {
        std::cout << x << ' ';            // 1 2 3
    }
    std::cout << '\n';

    std::stack<int> pila;
    pila.push(1);
    pila.push(2);
    std::cout << pila.top() << '\n';      // 2
    pila.pop();

    std::queue<std::string> cola;
    cola.push("primero");
    cola.push("segundo");
    std::cout << cola.front() << '\n';    // primero
    cola.pop();
    return 0;
}

#include <iostream>
#include <map>
#include <string>
#include <vector>

int main() {
    std::vector<std::string> palabras{"sol", "mar", "sol", "viento", "mar", "sol"};
    std::map<std::string, int> frecuencia;

    for (const std::string& p : palabras) {
        ++frecuencia[p];   // si no existe, la crea con 0 y suma 1
    }

    for (const auto& [palabra, veces] : frecuencia) {
        std::cout << palabra << ": " << veces << '\n';
    }
    return 0;
}

