#include <iostream>
#include <map>
#include <string>

int main() {
    std::string texto = "banana";
    std::map<char, int> frecuencia;

    for (char c : texto) {
        ++frecuencia[c];
    }

    for (const auto& [letra, veces] : frecuencia) {
        std::cout << letra << ": " << veces << '\n';
    }
    return 0;
}

#include <iostream>
#include <queue>
#include <vector>

int main() {
    std::priority_queue<int> urgentes;
    for (int u : {3, 1, 4, 1, 5, 9, 2, 6}) {
        urgentes.push(u);
    }

    while (!urgentes.empty()) {
        std::cout << urgentes.top() << ' ';
        urgentes.pop();
    }
    std::cout << '\n';   // 9 6 5 4 3 2 1 1

    // Para el orden inverso:
    // std::priority_queue<int, std::vector<int>, std::greater<int>> menores;
    return 0;
}

